pub fn init(root: &Path, opts: InitOptions) -> Result<Value> {
    let gov = root.join("governance");
    // AR88-C10B (P2-AR-0089): captured BEFORE `install_kernel` below can create it, so `--force` on an
    // ALREADY-onboarded project is distinguishable from a genuinely first install. `--force` bypasses
    // ALREADY_INSTALLED to let the KERNEL be reinstalled -- it must not also re-derive and rewrite the
    // AUTHORITATIVE adoption floor. Measured: without this guard, `mv src elsewhere && gov init --force` produced
    // an authenticated, forward-sequenced, freshly sealed floor with NO CIT, NO Human Gate and NO owner, as plain
    // role `orchestrator` -- an authenticated transition that was never an AUTHORISED one (OD-P2-08 §2). See
    // `write_project_adoption_floor`'s own doc.
    let already_installed = gov.join("framework.lock").exists();
    if already_installed && !opts.force {
        return Err(GovError::new("ALREADY_INSTALLED", format!("{} already has a Governance OS installation (use gov update, or --force to reinstall the kernel)", root.display())));
    }
    {
        // BC-P2-08 at the ingress itself (IP-7, WS-3's resolution API): the acting role is the one this process
        // resolved (`authority::default_role_id`, through `Project::open`), and an uninstalled repository is checked
        // against the constitution embedded in this binary — before anything is staged or written. The CLI's G0 makes
        // the same decision first; this keeps the library entry point from being the weaker door.
        let p0 = Project::open(root);
        if p0.is_installed() {
            crate::authority::require(&p0, "install_kernel")?;
        } else {
            crate::authority::require_with_embedded_kernel(&p0.role, "install_kernel")?;
        }
    }
    let src = resolve_kernel_source(opts.source.as_deref().map(Path::new))?;
    // Privileged lifecycle ingress `init`: the one verification policy (ARCH-0003 §3.6, §6). The floors bind this
    // ingress like every other one — they are a property of the machine, not of one operation.
    let auth = crate::srr::admit(
        crate::srr::AdmissionRequest::new(crate::srr::Ingress::Init, &src)
            .with_channel(opts.channel.clone())
            .with_break_glass(opts.break_glass)
            .with_reason(Some("gov init".into())),
    )?;
    std::fs::create_dir_all(&gov)?;
    let manifest = install_kernel(&auth, &gov)?;
    let consumer_commit = Project::open(root).git_commit();
    let release_commit = crate::kernel::release_commit_for_source(&src);
    let lock = write_lock(
        &gov.join("framework.lock"),
        &manifest,
        &crate::kernel::source_label(&src),
        Some(&release_commit),
        Some(&consumer_commit),
    )?;
    let (mut contract, adoption_floor) = contract_with_native_layout(&gov.join("kernel"), root)?;
